function [l_max] = highest_level(levels)
%HIGHEST_LEVEL  The highest open risk level over the seven areas (0 none open ... 5 would stop delivery).
%   levels: int[7] (passed a whole number)
%   returns l_max: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    l_max = 0;
    l_max = levels(1);
    for k = (1):((7) - 1)
        h__25 = l_max;
        h__26 = levels((k) + 1);
        if h__26 > h__25, h__25 = h__26; end
        l_max = h__25;
    end
end
